constexpr uint16_t kKeysLayout = 1U;
constexpr uint16_t kNetLayout = 1U;
constexpr char kCompiledId[] = "k0";

void copyText(char* out, size_t cap, const char* in) {
  const size_t n = in == nullptr ? 0U : strlen(in);
  if (n + 1U > cap) {
    out[0] = '\0';
    return;
  }
  memcpy(out, in == nullptr ? "" : in, n + 1U);
}

bool isCompiled(const char* id) {
  return strcmp(id, kCompiledId) == 0;
}

bool validKey(const char* key) {
  if (key == nullptr || strlen(key) != devnet::kKeyLen) {
    return false;
  }
  for (size_t i = 0U; i < devnet::kKeyLen; ++i) {
    const char c = key[i];
    const bool ok =
        (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_';
    if (!ok) {
      return false;
    }
  }
  return true;
}

bool validId(const char* id) {
  const size_t n = id == nullptr ? 0U : strlen(id);
  if (n < 2U || n > 7U || id[0] != 'k' || id[1] < '1' || id[1] > '9') {
    return false;
  }
  for (size_t i = 2U; i < n; ++i) {
    if (id[i] < '0' || id[i] > '9') {
      return false;
    }
  }
  return true;
}

/// The ONE staging copy each kind of record is adopted through: one loop,
/// never re-entered, so every adopt shares it (statics, never frames: ESPR-1).
devnet::NetSet gStagedNet;
devnet::KeyRing gStagedRing;

bool sameProfile(const devnet::Profile& a, const devnet::Profile& b) {
  return strcmp(a.ssid, b.ssid) == 0 && strcmp(a.psk, b.psk) == 0;
}

