// --- BridgeKeys -------------------------------------------------------------------

void BridgeKeys::begin(const char* compiledKey, IFiles* files) {
  compiled_ = compiledKey == nullptr ? "" : compiledKey;
  files_ = files;
  if (files_ == nullptr || !sealedGet(*files_, kFileKeys, kKeysLayout, ring_) || ring_.currentId[0] != 'k') {
    ring_ = devnet::KeyRing();
    memcpy(ring_.currentId, kCompiledId, sizeof(kCompiledId));
  }
  onPrevious_ = false;
  render();
}

void BridgeKeys::render() {
  const char* id = onPrevious_ ? ring_.previousId : ring_.currentId;
  const char* key = onPrevious_ ? ring_.previousKey : ring_.currentKey;
  if (isCompiled(id)) {
    key = compiled_;
  }
  if (devapi::renderAuthorization(header_, sizeof(header_), key) == 0U) {
    header_[0] = '\0';
  }
}

bool BridgeKeys::switchForRetry() {
  if (!ring_.hasPrevious) {
    return false;
  }
  onPrevious_ = !onPrevious_;
  render();
  return true;
}

void BridgeKeys::retryFailed() {
  if (!ring_.hasPrevious) {
    return;
  }
  onPrevious_ = !onPrevious_;
  render();
}

bool BridgeKeys::persist(const devnet::KeyRing& ring) {
  return files_ == nullptr || sealedPut(*files_, kFileKeys, kKeysLayout, ring);
}

devnet::Refusal BridgeKeys::adopt(const char* object, size_t len) {
  // `k0`'s text lives in the image, not the ring; the shared reader keeps a
  // previous key only when the current one has text, so k0 is given a marker
  // `render` never sends (it sends the compiled key for any `k0`).
  // The ring itself is the view, the marker put in and taken out again: a
  // third ring would be 115 bytes the heap floor does not have.
  devnet::KeyRing& next = gStagedRing;
  const bool marked = isCompiled(ring_.currentId) && ring_.currentKey[0] == '\0';
  if (marked) {
    ring_.currentKey[0] = '-';
    ring_.currentKey[1] = '\0';
  }
  const devnet::Refusal got = devnet::adoptKeyNext(object, len, ring_, next);
  if (marked) {
    ring_.currentKey[0] = '\0';
    if (got == devnet::Refusal::Ok && strcmp(next.previousId, kCompiledId) == 0) {
      next.previousKey[0] = '\0'; // k0's text stays in the image
    }
  }
  if (got != devnet::Refusal::Ok) {
    return got;
  }
  // PERSISTED BEFORE IT IS USED: a board that authenticated with a key it then
  // lost in a power cut would be on a key the server thinks it holds and it
  // does not.
  if (!persist(next)) {
    return devnet::Refusal::Key;
  }
  ring_ = next;
  onPrevious_ = false;
  render();
  return got;
}

bool BridgeKeys::adoptLocal(const char* id, const char* key) {
  if (!validId(id) || !validKey(key)) {
    return false;
  }
  devnet::KeyRing& next = gStagedRing;
  next = devnet::KeyRing();
  memcpy(next.currentId, id, strlen(id) + 1U);
  memcpy(next.currentKey, key, devnet::kKeyLen + 1U);
  next.hasPrevious = true;
  memcpy(next.previousId, ring_.currentId, sizeof(next.previousId));
  memcpy(next.previousKey, ring_.currentKey, sizeof(next.previousKey));
  if (!persist(next)) {
    return false;
  }
  ring_ = next;
  onPrevious_ = false;
  render();
  return true;
}

// --- BridgeNet --------------------------------------------------------------------

const char* netSourceName(NetSource source) {
  switch (source) {
  case NetSource::Server:
    return "server";
  case NetSource::Local:
    return "local";
  case NetSource::Compiled:
    break;
  }
  return "compiled";
}

void BridgeNet::begin(const char* ssid, const char* psk, const char* baseUrl, IFiles* files) {
  files_ = files;
  copyText(compiled_.ssid, sizeof(compiled_.ssid), ssid);
  copyText(compiled_.psk, sizeof(compiled_.psk), psk);
  compiledBase_ = baseUrl == nullptr ? "" : baseUrl;
  if (files_ == nullptr || !sealedGet(*files_, kFileNet, kNetLayout, record_)) {
    record_ = NetRecord();
  }
  active_ = 0U;
}

const char* BridgeNet::baseUrl() const {
  if (record_.meta.hasCurrent != 0U && record_.current.hasBase) {
    return record_.current.base;
  }
  if (record_.meta.hasPrevious != 0U && record_.previous.hasBase) {
    return record_.previous.base;
  }
  return compiledBase_;
}

const devnet::Profile* BridgeNet::profileAt(uint8_t index) const {
  // Current set's profiles, then the previous set's, then the compiled one;
  // each distinct profile once, in that order (§8).
  const devnet::Profile* seen[2U * devnet::kProfiles + 1U] = {};
  uint8_t count = 0U;
  const auto offer = [&](const devnet::Profile* p) {
    if (p == nullptr || p->ssid[0] == '\0') {
      return;
    }
    for (uint8_t i = 0U; i < count; ++i) {
      if (sameProfile(*seen[i], *p)) {
        return;
      }
    }
    seen[count] = p;
    ++count;
  };
  for (uint8_t w = 0U; w < devnet::kProfiles; ++w) {
    offer(record_.meta.hasCurrent != 0U && record_.current.hasWifi[w] ? &record_.current.wifi[w] : nullptr);
  }
  for (uint8_t w = 0U; w < devnet::kProfiles; ++w) {
    offer(record_.meta.hasPrevious != 0U && record_.previous.hasWifi[w] ? &record_.previous.wifi[w]
                                                                        : nullptr);
  }
  offer(&compiled_);
  return index < count ? seen[index] : nullptr;
}

uint8_t BridgeNet::profileCount() const {
  uint8_t n = 0U;
  while (n < 2U * devnet::kProfiles + 1U && profileAt(n) != nullptr) {
    ++n;
  }
  return n;
}

const char* BridgeNet::ssid(uint8_t index) const {
  const devnet::Profile* p = profileAt(index);
  return p == nullptr ? "" : p->ssid;
}

const char* BridgeNet::psk(uint8_t index) const {
  const devnet::Profile* p = profileAt(index);
  return p == nullptr ? "" : p->psk;
}

uint8_t BridgeNet::advanceProfile() {
  const uint8_t n = profileCount();
  active_ = static_cast<uint8_t>((active_ + 1U) % (n == 0U ? 1U : n));
  return active_;
}

bool BridgeNet::persist(const NetMeta& meta, const devnet::NetSet& current, const devnet::NetSet& previous) {
  if (files_ == nullptr) {
    return true;
  }
  // Written from its three parts, so no second copy of two network sets is
  // ever held to write it (ESPR-1, the heap floor).
  const Part parts[3] = {{const_cast<NetMeta*>(&meta), sizeof(meta)},
                         {const_cast<devnet::NetSet*>(&current), sizeof(current)},
                         {const_cast<devnet::NetSet*>(&previous), sizeof(previous)}};
  static_assert(sizeof(NetRecord) == sizeof(NetMeta) + 2U * sizeof(devnet::NetSet),
                "the record is read back as one struct: no padding between its parts");
  return sealedWrite(*files_, kFileNet, kNetLayout, parts, 3U);
}

uint32_t BridgeNet::version() const {
  return record_.meta.hasCurrent != 0U && record_.meta.source == static_cast<uint8_t>(NetSource::Server)
             ? record_.current.ver
             : 0U;
}

devnet::NetResult BridgeNet::adopt(const char* object, size_t len, uint32_t nowMs) {
  devnet::NetSet& staged = gStagedNet;
  staged = devnet::NetSet();
  devnet::NetResult result = devnet::adoptNet(object, len, version(), staged);
  if (!result.adopted()) {
    return result;
  }
  if (staged.ver == record_.meta.abandonedVer) {
    result.reason = devnet::Refusal::NotNewer;
    return result;
  }
  // Absent base: the one in use carries over. Absent profiles: as sent, and
  // the previous set still holds the ones in use.
  const char* inUse = baseUrl();
  if (!staged.hasBase) {
    copyText(staged.base, sizeof(staged.base), inUse);
    staged.hasBase = true;
  }
  NetMeta meta = record_.meta;
  const bool hadCurrent = meta.hasCurrent != 0U;
  meta.hasPrevious = hadCurrent ? 1U : meta.hasPrevious;
  meta.hasCurrent = 1U;
  meta.source = static_cast<uint8_t>(NetSource::Server);
  meta.baseUnproven = strcmp(staged.base, inUse) != 0 ? 1U : 0U;
  const devnet::NetSet& previous = hadCurrent ? record_.current : record_.previous;
  if (!persist(meta, staged, previous)) {
    // Nothing changed in RAM: a set that is not in flash is not adopted.
    result.reason = devnet::Refusal::NetEmpty;
    return result;
  }
  if (hadCurrent) {
    record_.previous = record_.current;
  }
  record_.current = staged;
  record_.meta = meta;
  adoptedAtMs_ = nowMs;
  active_ = 0U;
  return result;
}

bool BridgeNet::adoptLocal(const devnet::NetSet& local) {
  devnet::NetSet& staged = gStagedNet;
  if (&staged != &local) {
    staged = local;
  }
  staged.ver = 0U;
  NetMeta meta = record_.meta;
  const bool hadCurrent = meta.hasCurrent != 0U;
  meta.hasPrevious = hadCurrent ? 1U : meta.hasPrevious;
  meta.hasCurrent = 1U;
  meta.source = static_cast<uint8_t>(NetSource::Local);
  meta.baseUnproven = 0U;
  const devnet::NetSet& previous = hadCurrent ? record_.current : record_.previous;
  if (!persist(meta, staged, previous)) {
    return false;
  }
  if (hadCurrent) {
    record_.previous = record_.current;
  }
  record_.current = staged;
  record_.meta = meta;
  active_ = 0U;
  return true;
}

void BridgeNet::heartbeatAccepted() {
  if (record_.meta.baseUnproven == 0U) {
    return;
  }
  NetMeta meta = record_.meta;
  meta.baseUnproven = 0U;
  if (persist(meta, record_.current, record_.previous)) {
    record_.meta = meta;
  }
}

bool BridgeNet::tick(uint32_t nowMs, uint32_t fallbackMinutes) {
  if (record_.meta.baseUnproven == 0U || tb::since(nowMs, adoptedAtMs_) < fallbackMinutes * 60000UL) {
    return false;
  }
  // ABANDONED: the previous base again, and this version never again. The WiFi
  // profiles stay; the supervisor tries them in order.
  record_.meta.abandonedVer = record_.current.ver;
  record_.meta.baseUnproven = 0U;
  record_.current.hasBase = false;
  record_.current.ver = record_.meta.hasPrevious != 0U ? record_.previous.ver : 0U;
  static_cast<void>(persist(record_.meta, record_.current, record_.previous));
  return true;
}

// --- the lifeline settings ----------------------------------------------------------

namespace {

/// The `config` object being read, and where an unreadable value is reported.
/// Built at run time: a table of constant keys and bounds would sit in the
/// ESP8266's DRAM (.rodata), above a heap floor with no room to spare.
struct ConfigObject {
  const char* obj;
  size_t len;
  Drift* drift;
};

void readClamped(const ConfigObject& in, const char* key, uint32_t lo, uint32_t hi, uint32_t& value) {
  if (devapi::json::findTopLevelKey(in.obj, in.len, key) == devapi::json::kNotFound) {
    return;
  }
  uint32_t v = 0U;
  if (!devapi::json::topLevelUnsignedField(in.obj, in.len, key, v)) {
    if (in.drift != nullptr) {
      char name[Drift::kNameLen] = "config.";
      strncat(name, key, sizeof(name) - strlen(name) - 1U);
      in.drift->add(name);
    }
    return;
  }
  value = v < lo ? lo : (v > hi ? hi : v);
}

} // namespace

void readLifelineSettings(const char* body, size_t len, LifelineSettings& current, Drift* drift) {
  size_t objLen = 0U;
  const size_t at = devapi::json::findTopLevelObject(body, len, "config", objLen);
  if (at == devapi::json::kNotFound) {
    return;
  }
  // findTopLevelObject points at the first byte INSIDE the braces; the readers
  // want the object with its braces.
  const char* obj = body + at - 1U;
  const ConfigObject in{obj, objLen + 2U, drift};
  readClamped(in, "device_power_restore_trust_minutes", 0U, 120U, current.trustMinutes);
  readClamped(in, "device_net_fallback_minutes", 3U, 60U, current.fallbackMinutes);
  readClamped(in, "relay_reconcile_min_seconds", 30U, 600U, current.reconcileMinSeconds);
}

// --- the stall watchdog ---------------------------------------------------------------

bool StallWatch::stalled(uint32_t nowMs, bool linkUp) {
  if (!linkUp) {
    // Down is the supervisor's problem; the stall clock is for an UP link that
    // keeps yielding and never delivers (HW-8).
    sinceMs_ = nowMs;
    return false;
  }
  return tb::since(nowMs, sinceMs_) >= kStallMs;
}

// --- the setup chord, the portal form -----------------------------------------------

bool SetupChord::held(const char* maskHex, const char* secondsText, uint32_t nowMs) {
  if (fired_ || maskHex == nullptr || secondsText == nullptr) {
    return false;
  }
  const unsigned long mask = strtoul(maskHex, nullptr, 16);
  const unsigned long seconds = strtoul(secondsText, nullptr, 10);
  if (mask != kMask || seconds < kHoldSeconds) {
    return false;
  }
  // The hold must have BEGUN inside the window: it ended now, `seconds` long.
  const uint32_t heldMs = static_cast<uint32_t>(seconds) * 1000UL;
  const uint32_t up = tb::since(nowMs, bootMs_);
  if (up < heldMs || up - heldMs > kWindowMs) {
    return false;
  }
  fired_ = true;
  return true;
}

bool urlDecode(const char* in, size_t inLen, char* out, size_t cap) {
  size_t n = 0U;
  for (size_t i = 0U; i < inLen; ++i) {
    char c = in[i];
    if (c == '+') {
      c = ' ';
    } else if (c == '%') {
      if (i + 2U >= inLen) {
        return false;
      }
      unsigned v = 0U;
      for (size_t k = 1U; k <= 2U; ++k) {
        const char h = in[i + k];
        v <<= 4;
        if (h >= '0' && h <= '9') {
          v |= static_cast<unsigned>(h - '0');
        } else if (h >= 'a' && h <= 'f') {
          v |= static_cast<unsigned>(h - 'a' + 10);
        } else if (h >= 'A' && h <= 'F') {
          v |= static_cast<unsigned>(h - 'A' + 10);
        } else {
          return false;
        }
      }
      if (v == 0U) {
        return false;
      }
      c = static_cast<char>(v);
      i += 2U;
    }
    if (n + 1U >= cap) {
      return false;
    }
    out[n] = c;
    ++n;
  }
  out[n] = '\0';
  return true;
}

namespace {

/// `in` escaped into `out` at `at`; advances `at`. False when it does not fit.
bool escapeAt(const char* in, char* out, size_t cap, size_t& at) {
  const char* text = in != nullptr ? in : "";
  if (at >= cap) {
    return false;
  }
  if (!devapi::json::escapeInto(text, strlen(text), out + at, cap - at)) {
    return false;
  }
  at += strlen(out + at);
  return true;
}

bool literalAt(const char* text, char* out, size_t cap, size_t& at) {
  const size_t n = strlen(text);
  if (at + n + 1U > cap) {
    return false;
  }
  memcpy(out + at, text, n + 1U);
  at += n;
  return true;
}

/// A key's literal, then `value` escaped into the JSON string after it.
bool pairAt(const char* literal, const char* value, char* out, size_t cap, size_t& at) {
  return literalAt(literal, out, cap, at) && escapeAt(value, out, cap, at);
}

/// The form written as the `net` object the server would have sent.
bool writePortalNet(const PortalForm& form, char* scratch, size_t cap, size_t& at) {
  at = 0U;
  bool ok = pairAt("{\"ver\":1,\"base\":\"", form.base, scratch, cap, at) &&
            pairAt("\",\"wifi0_ssid\":\"", form.ssid, scratch, cap, at) &&
            pairAt("\",\"wifi0_psk\":\"", form.psk, scratch, cap, at);
  const bool second = form.ssid2 != nullptr && form.ssid2[0] != '\0';
  if (ok && second) {
    ok = pairAt("\",\"wifi1_ssid\":\"", form.ssid2, scratch, cap, at) &&
         pairAt("\",\"wifi1_psk\":\"", form.psk2, scratch, cap, at);
  }
  return ok && literalAt("\"}", scratch, cap, at);
}

} // namespace

devnet::Refusal validatePortalForm(const PortalForm& form, devnet::NetSet& out, char* scratch,
                                   size_t scratchCap) {
  // THE SAME RULES AS A SERVER `net`, by construction: the form is written as
  // the object the server would have sent and read by the same reader.
  size_t at = 0U;
  if (scratch == nullptr || scratchCap == 0U || !writePortalNet(form, scratch, scratchCap, at)) {
    return devnet::Refusal::TooLong;
  }
  devnet::NetSet staged;
  const devnet::NetResult r = devnet::adoptNet(scratch, at, 0U, staged);
  if (!r.adopted()) {
    return r.reason;
  }
  staged.ver = 0U;
  out = staged;
  return devnet::Refusal::Ok;
}

bool setupApName(const char* macHex, char* out, size_t cap) {
  const size_t n = macHex == nullptr ? 0U : strlen(macHex);
  if (n < 4U) {
    return false;
  }
  char last4[5] = {};
  for (uint8_t i = 0U; i < 4U; ++i) {
    const char c = macHex[n - 4U + i];
    last4[i] = (c >= 'a' && c <= 'f') ? static_cast<char>(c - 'a' + 'A') : c;
  }
  const int w = snprintf(out, cap, "CRUSADERS-SETUP-%s", last4);
  return w > 0 && static_cast<size_t>(w) < cap;
}

